    CAR_RIM_GOLD: '#e8c877',
    CAR_LIGHT_AMBER: '#ff9a2a',
    CAR_LIGHT_COOL:  '#8fe8ff',
    CAR_SEAM_GOLD: 'rgba(232,200,119,0.5)',
  /* ITEM 5's TWO ENDS. The key is authored at the car's own measured peak
       so the brightest lit face lands where the brightest hand authored
       face lands now, and the ambient is a cool dark the unlit faces fall
       to. In the car role, so both turn with the place. */
