  /* L7554 */ function drawBrand(g, art, cx, cy, width, alpha) {
    if (!art.path || !(width > 0)) return 0;
    const k = width / art.w;
    const height = art.h * k;
    g.save();
    if (alpha !== undefined) g.globalAlpha = alpha;
    // Into the artwork's own coordinate space, viewBox origin included, so
    // everything below is written in the numbers the export used.
    g.translate(cx - width / 2, cy - height / 2);
    g.scale(k, k);
    g.translate(-art.x, -art.y);
    g.lineJoin = 'round';
    g.lineCap = 'round';
    g.lineWidth = art.stroke;
  
    g.save();
    g.translate(art.dx, art.dy);
    g.fillStyle = BRAND.SHADOW;
    g.strokeStyle = BRAND.SHADOW;
    g.fill(art.path, 'evenodd');
    g.stroke(art.path);
    g.restore();
  
    g.strokeStyle = BRAND.OUTLINE;
    g.stroke(art.path);
  
    g.fillStyle = BRAND.FILL;
    g.fill(art.path, 'evenodd');
    g.restore();
    return height;
  }

