  /* L7628 */ function brandBitmap(art, boxW, boxH, dpr) {
    const pw = Math.max(1, Math.round(boxW * dpr));
    const ph = Math.max(1, Math.round(boxH * dpr));
    const key = pw + 'x' + ph;
    if (art.cacheKey === key && art.cache) return art.cache;
    let c = art.cache;
    if (!c) { c = document.createElement('canvas'); art.cache = c; }
    c.width = pw;
    c.height = ph;
    const g = c.getContext('2d');
    if (!g) { art.cache = null; return null; }
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, pw, ph);
    drawBrand(g, art, pw / 2, ph / 2, pw);
    art.cacheKey = key;
    return c;
  }

  /* L7662, 3 SIM refs */ function brandText(str, cx, cy, size, alpha) {
    ctx.save();
    if (alpha !== undefined) ctx.globalAlpha = alpha;
    ctx.font = '900 ' + size + 'px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    ctx.lineWidth = size * SIM.FEEL.BRAND_TEXT_STROKE;
    const dx = size * SIM.FEEL.BRAND_TEXT_SHADOW_X;
    const dy = size * SIM.FEEL.BRAND_TEXT_SHADOW_Y;
    ctx.fillStyle = BRAND.SHADOW;
    ctx.strokeStyle = BRAND.SHADOW;
    ctx.strokeText(str, cx + dx, cy + dy);
    ctx.fillText(str, cx + dx, cy + dy);
    ctx.strokeStyle = BRAND.OUTLINE;
    ctx.strokeText(str, cx, cy);
    ctx.fillStyle = BRAND.FILL;
    ctx.fillText(str, cx, cy);
    ctx.restore();
  }

