    view.w = w;
    view.h = h;
    view.dpr = dpr;
    // Live tuning calls this many times a second while a button is held, and
    // assigning width or height reallocates the backing store even when the
    // value has not changed. Only touch it when it actually moved.
    const cw = Math.round(w * dpr), ch = Math.round(h * dpr);
    if (canvas.width !== cw) canvas.width = cw;
    if (canvas.height !== ch) canvas.height = ch;
  
    horizonY = Math.round(h * SIM.FEEL.HORIZON_FRACTION);
    /* THE SPRITE ATLAS IS SIZED AGAINST THE FRAME WIDTH AND THE DEVICE
       RATIO, so this is the one place that can know when it needs
       rebuilding. spriteBuildAtlas compares its own signature and returns
       immediately when nothing it reads has moved, which matters because
       live tuning calls resize many times a second while a button is held
       and because one fullscreen tap calls it three times. */
    spriteBuildAtlas();
  
    const probe = window.getComputedStyle(document.getElementById('safe'));
    safeBottom = parseFloat(probe.paddingBottom) || 0;
    /* The top inset only bites in fullscreen, where the browser chrome is
       no longer sitting over the cutout for us. resize already runs on
       rotation and on entering and leaving fullscreen, which is exactly the
       three moments this changes. */
    safeTop = parseFloat(probe.paddingTop) || 0;
    /* WHERE THE CORNER PADS START, measured rather than derived. The pad
       row's height is a fixed pixel size in the stylesheet with four media
       queries on it, while everything on the canvas is a fraction of the
       smaller screen dimension. On a tablet those two disagree badly
       enough that a canvas button sized in s reaches down into a pad row
       sized in pixels, which is exactly what the share button did at 768
       wide. Read here, on the three occasions it can change, so nothing in
       the draw loop ever touches layout. */
    const padRow = document.getElementById('pads');
    const padBox = padRow ? padRow.getBoundingClientRect() : null;
    /* A zero height means the row is display:none, which it is for the
       whole of the boot flash. Fall back to the bottom of the safe area,
       which constrains nothing, rather than to zero, which would push
       every button that respects this clean off the top of the screen.
       endBootChrome calls resize again the moment the row exists. */
    padsTop = (padBox && padBox.height > 0) ? padBox.top : (h - safeBottom);
